'use strict';

// AI: below section was generated by an AI
// Exercise the actual settings-page functions without requiring a running ESP32.
const assert = require('node:assert/strict');
const { test } = require('node:test');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');

function settings(profile = [64, 16, 4, 16, 2], busTypes = [72]) {
  const form = {
    data: { value: '' }, MA: { value: 0 }, ABL: { checked: false }, PPL: { checked: false },
    checkValidity: () => true,
  };
  const selects = busTypes.map((value, i) => ({ name: `LT${i}`, value, disabled: false }));
  selects.forEach((select, i) => {
    form[`LT${i}`] = select;
    form[`LC${i}`] = { value: 1024 };
    form[`SL${i}`] = { value: 0 };
    profile.forEach((value, p) => { form[`L${p}${i}`] = { name: `L${p}${i}`, value, dataset: {} }; });
  });
  form.querySelectorAll = selector => {
    if (selector === 'select.pin') return [];
    if (selector.includes('input[name^=L],') || selector.startsWith('.iST')) return Object.values(form).filter(el => /^L[0-4]/.test(el?.name));
    return selects;
  };
  const context = vm.createContext({
    document: { createElement: () => ({}), head: { appendChild() {} } },
    d: { Sf: form, rsvd: [], um_p: [], ro_gpio: [], ledTypes: [{ i: 72, t: 'T', c: 1 }, { i: 22, t: 'D', c: 1 }, { i: 65, t: 'H', c: 1 }] },
    alerts: [], submitted: false,
  });
  const html = fs.readFileSync(path.join(__dirname, '../wled00/data/settings_leds.htm'), 'utf8');
  vm.runInContext(html.match(/<script>([\s\S]*?)<\/script>/)[1], context);
  vm.runInContext(`
    chipID = 4; maxRMT = 8; maxI2S = 0; bquot = 0;
    alert = message => alerts.push(message);
    realPinsOK = pinsOK;
    pinsOK = () => true;
    isBCok = () => true;
    getDuse = () => ({rmtUsed: 0, i2sUsed: 0});
    d.Sf.submit = () => { submitted = true; };
  `, context);
  return context;
}

function submit(context) {
  vm.runInContext('trySubmit({preventDefault() {}, stopPropagation() {}})', context);
}

test('LedTile configuration slots are panel parameters, not digital GPIOs', () => {
  const context = settings();
  assert.equal(vm.runInContext('isTile(72) && isPanel(72) && !isDig(72)', context), true);
  assert.equal(vm.runInContext('isPanel(65) && !isTile(65)', context), true);
  assert.equal(vm.runInContext('isDig(22) && !isPanel(22)', context), true);
});

test('conservative profile includes waveform, driver and WLED pixel memory', () => {
  assert.equal(vm.runInContext('getMem(72, "0")', settings()), 70304 + 8192 + 8192);
});

test('geometry and bounds are set while saved BCM timing is preserved', () => {
  const context = settings([64, 16, 5, 8, 1]);
  vm.runInContext('configureTile("0", false)', context);
  assert.equal(context.d.Sf.L20.value, 5);
  assert.equal(context.d.Sf.L30.value, 8);
  assert.equal(context.d.Sf.L40.value, 1);
  assert.equal(context.d.Sf.L00.min, 64);
  assert.equal(context.d.Sf.L00.max, 64);
  assert.equal(context.d.Sf.L00.readOnly, true);
  assert.equal(context.d.Sf.L20.max, 8);
  assert.equal(context.d.Sf.LC0.value, 1024);
  vm.runInContext('configureTile("0", true)', context);
  assert.equal(context.d.Sf.L20.value, 4);
  assert.equal(context.d.Sf.L30.value, 16);
  assert.equal(context.d.Sf.L40.value, 2);
});

test('valid single-panel settings submit', () => {
  const context = settings();
  submit(context);
  assert.equal(context.submitted, true);
  assert.equal(context.alerts.length, 0);
});

for (const profile of [[32,16,4,16,2], [64,16,0,16,2], [64,16,9,16,2],
  [64,16,4,1,1], [64,16,4,256,2], [64,16,4,16,0], [64,16,4,16,16], [64,16,4.5,16,2]]) {
  test(`invalid LedTile profile ${profile} does not submit`, () => {
    const context = settings(profile);
    submit(context);
    assert.equal(context.submitted, false);
    assert.equal(context.alerts.length, 1);
  });
}

test('two tiles cannot submit', () => {
  const context = settings(undefined, [72, 72]);
  submit(context);
  assert.equal(context.submitted, false);
});

test('I2S strips cannot share the panel peripheral', () => {
  const context = settings();
  vm.runInContext('getDuse = () => ({rmtUsed: 0, i2sUsed: 1})', context);
  submit(context);
  assert.equal(context.submitted, false);
});

test('panel timing slots do not conflict with reserved GPIO numbers', () => {
  const context = settings();
  vm.runInContext('d.um_p = [16, 2, 4]; pinsOK = realPinsOK', context);
  assert.equal(vm.runInContext('pinsOK()', context), true);
});

test('GPIO dropdown refresh leaves all five panel profile inputs numeric', () => {
  const context = settings();
  vm.runInContext(`
    converted = [];
    makePinSelect = name => { converted.push(name); return null; };
    gId = () => ({querySelectorAll: () => []});
    pinDropdowns();
  `, context);
  assert.equal(context.converted.some(name => /^L[0-4]/.test(name)), false);
});

test('additional RMT strips are permitted', () => {
  const context = settings(undefined, [72, 22]);
  vm.runInContext('getDuse = () => ({rmtUsed: 1, i2sUsed: 0})', context);
  submit(context);
  assert.equal(context.submitted, true);
});

test('RMT exhaustion cannot silently fall back to the panel I2S peripheral', () => {
  const context = settings();
  vm.runInContext('getDuse = () => ({rmtUsed: 9, i2sUsed: 0})', context);
  submit(context);
  assert.equal(context.submitted, false);
});
